// Native evaluation harness. All generated objects are evaluation data, not save schemas.
package main
import("encoding/json";"os";"fmt";"reflect";"time"; p "github.com/opd-ai/venture/pkg/procgen"; e "github.com/opd-ai/venture/pkg/procgen/entity"; i "github.com/opd-ai/venture/pkg/procgen/item"; q "github.com/opd-ai/venture/pkg/procgen/quest"; n "github.com/opd-ai/venture/pkg/procgen/narrative"; f "github.com/opd-ai/venture/pkg/procgen/faction"; m "github.com/opd-ai/venture/pkg/procgen/magic";d "github.com/opd-ai/venture/pkg/procgen/dialog")
func main(){dg:=d.NewMarkovGenerator(78000,"fantasy",d.Order2);dg.TrainFromCorpus(d.GetFantasyCorpus().Sentences);out:=map[string]interface{}{}; metrics:=map[string]interface{}{};gens:=map[string]p.Generator{"entity":e.NewEntityGenerator(),"item":i.NewItemGenerator(),"quest":q.NewQuestGenerator(),"narrative":n.NewStoryArcGenerator(),"faction":f.NewGenerator(),"magic":m.NewSpellGenerator(),"dialog":dg}; for name,g:=range gens{count:=100;rows:=[]interface{}{};fails:=[]string{};replay:=true;start:=time.Now();for k:=0;k<count;k++{params:=p.GenerationParams{GenreID:"fantasy",Difficulty:0.4,Depth:2,Custom:map[string]interface{}{"count":1}};a,err:=g.Generate(int64(78000+k),params);if err!=nil{fails=append(fails,err.Error());continue}; b,err:=g.Generate(int64(78000+k),params);if err!=nil||!reflect.DeepEqual(a,b){replay=false};validationTarget:=a;if name=="faction"{validationTarget=params};if err:=g.Validate(validationTarget);err!=nil{fails=append(fails,"validate:"+err.Error())};rows=append(rows,a)};out[name]=rows;metrics[name]=map[string]interface{}{"calls":count,"outputs":len(rows),"replay_equal":replay,"errors":fails,"milliseconds":time.Since(start).Milliseconds()}};out["metrics"]=metrics; enc:=json.NewEncoder(os.Stdout);enc.SetIndent("","  ");if err:=enc.Encode(out);err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)}}
